-- The 59 spells of Bone Magic, the Necromancer's tradition.
-- Rifts World Book 18: Mystic Russia pp.92-105. Batch 1b of the mystic-russia
-- ingestion, and the book's LARGEST tradition.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/zzzzzzzzzz-mr-bone-spells.sql
--
-- Read from the book's TEXT LAYER (.cache/books/mystic-russia, page_offset 1)
-- and parsed, by the same reader that produced the Spoiling batch - re-run
-- against those 18 after the changes below and confirmed byte-identical, so
-- nothing already in production shifted under this.
--
-- Names take the `Bone: ` prefix per DECISION D1 in
-- apps/character-creator/docs/surveys/mystic-russia.md. NONE of the 59 collides
-- with an existing row - checked with tradition prefixes and trailing plurals
-- folded, then spot-checked by keyword against every catalog name holding
-- "animate", "death", "vampire" or "necro" - so no row needs `same_spell_as`
-- and NO EXISTING ROW CHANGES VALUE.
--
-- TWO NAMES CARRY A COLON OF THEIR OWN and keep it: `Bone: Curse: Death Wish`
-- and `Bone: Curse: To Hell & Back`. The book prints them that way, the
-- catalog already holds general invocations shaped like `Curse: Phobia`, and
-- the prefix still reads back correctly because it is cut at the FIRST ": ".
-- Renaming them to fit would have been the bigger change.
--
-- `tradition = 'bone'` is its own value, not shared with the book's other
-- three: the tradition gates which classes may reach these spells, and Bone
-- Magic belongs to the Necromancer alone.
--
-- Levels run L1:5 L2:4 L3:4 L4:7 L5:6 L6:2 L7:1 L8:4 L9:6 L10:4 L11:4 L12:6 L13:5 L14:1 - all fourteen, no gaps.
--
-- 23 costs are schedules rather than plain numbers, so `ppe` holds the
-- figure the sheet can spend and `ppe_note` carries the rest, per migration
-- 021. Two are the book spelling a small number as a WORD ("Two points"), and
-- Return from the Grave is "Special; a total of 60 P.P.E. and 24 hit points are
-- permanently spent" - `ppe` takes the 60 because the 24 hit points is a
-- second cost nothing models, and the note keeps the whole sentence.
--
-- THE PARSE TRAP THIS TRADITION ADDED, recorded in the survey: a SUMMONING
-- spell prints the summoned creature's own stat block inside its description -
-- `Damage:`, `Horror Factor:`, `M.D.C.:` - and `Damage:` is also a spell
-- header field. Reading it as one made Summon Magot's cost absorb the thirteen
-- lines between. The header is now taken as the run of labels up to and
-- INCLUDING the cost, which is always last; a label after it is prose.

INSERT INTO spells
  (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition)
VALUES
  ('Bone: Animate Body Parts', 1, 2, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.92', 'rifts', '20 feet (6 m) per level of experience.', 'Two minutes per level of the Necromancer.', NULL, 'Not Applicable', NULL, NULL, 'Limitations: One body part per level of the Necromancer. The inexperienced Necromancer is able to animate the appendages and parts of the dead, such as hands and arms, feet, legs, tail, wings, mouth (to bite or mouth words), etc., but not the entire body. Also ideal for manipulating dismembered limbs. If connected to an entire body, one body part (per level of the spell caster) can be animated and controlled. Thus, the hand and arm of a corpse or skeleton could be made to reach out and grab or hit somebody, but little more. Dismembered limbs can be made to move along the ground by crawling, jumping or sliding; speed of 5. The Necromancer has complete mental control over the body parts he can manipulate. Each motion/action of the body part(s) counts as one of his melee actions. If the Necromancer is rendered unconscious or slain, the spell is immediately broken and the limb/part slumps lifelessly to the ground. A successful Turn the Dead will instantly cancel the spell.', NULL, 'bone'),
  ('Bone: Assemble Bones', 1, 2, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.92', 'rifts', 'Touch or within 60 feet (18.3 m) +20 feet (6 m) per level of experience.', 'Permanently assembled, although the bone can be easily moved or knocked apart.', NULL, 'Not applicable, enchantment is used on the bones of the dead.', NULL, NULL, 'This spell magically assembles loose bones in one melee round (15 seconds). As much as two complete, human-sized skeletons can be pieced together (roughly 80 lbs/36 kg of bones). If the bones are a loose pile of incomplete skeletons, the spell will assemble what it can and then gather the rest of the bones by type, i.e. all rib bones in one row, femurs in another, etc.', NULL, 'bone'),
  ('Bone: Bone & Joint Bonding', 1, 2, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.92', 'rifts', 'Touch or within 60 feet (18.3 m) +20 feet (6 m) per level of experience.', 'Permanent, although the bones and joints can be chopped apart.', NULL, 'Not applicable, enchantment is used on the bones of the dead.', NULL, NULL, 'This spell creates permanent, sinewy-like bonds and a flexible adhesive to hold bones together and create bendable joints. This is part of the magic involved in animating skeletons and crawling bones; how else could a skeleton stay together and move without real cartilage and muscle? This magical compound is virtually undetectable. The equivalent of one entire human-sized skeleton can be assembled and bonded together, with bendable joints.', NULL, 'bone'),
  ('Bone: Rattling Bones', 1, 2, '2 points', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.92', 'rifts', 'Touch or within 60 feet (18.3 m).', '10 minutes per level of experience.', NULL, 'Not applicable, enchantment is used on the bones of the dead.', NULL, NULL, 'A Necromancer spell used to unnerve people and create an air of fear. In this case, the magic can make a skeleton or equivalent amount of loose bones tremble. This causes the teeth of a skull to chatter and bones to rattle against each and/or on the floor. The rattling nose combined with seeing a skeleton or bones moving, even though restricted to one place, is frightening. The effect is equal to a Horror Factor of 15. Superstitious people and children are -4 to save vs H.F. All others who fail to save suffer the usual penalties for H.F. for one melee round, but the initiative penalty remains in effect for the entire time the bones rattle. Those who successfully save suffer no penalties.', NULL, 'bone'),
  ('Bone: Talking Bones', 1, 3, '3 points', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.92', 'rifts', 'Touch or within 60 feet (18.3 m).', '10 minutes per level of experience.', NULL, 'Not applicable, enchantment is used on the bones of the dead.', NULL, NULL, 'This is more of an unnerving trick, a sort of magical ventriloquism, than a powerful magic. The Necromancer can make the skull of any creature seem to talk. The words are his, but the voice is different, raspy and husky, and clearly comes from the skull. The initial words spoken by the skull are startling and frightening; equal to a Horror Factor of 13. Superstitious people and children are -4 to save vs H.F. and likely to flee the area. All others who fail to save suffer the usual penalties for H.F. for one melee round. As a magical form of ventriloquism, even if the Necromancer is within view, his mouth does not seem to move, and sound will not seem to be coming from him. In addition, the mage can leave the area and have the skull repeat one simple six word phrase over and over for the duration of the magic, even if he is miles away. This can be a menacing howl, moaning, wailing, or diabolical laughter, or words like, "go no further," or "beyond that door awaits death," or "now you die," or "beware, beware, beware ..." and so on. Note that while most frequently used to frighten and intimidate, this magic can also be used to deliver warnings or information, fake seances, and so on, without the Necromancer revealing his true identity. Level Two', NULL, 'bone'),
  ('Bone: Crawling Bones', 2, 5, '5 points', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.93', 'rifts', 'Touch or within 60 feet (18.3 m).', 'Five minutes per level of experience.', NULL, 'Not applicable, enchantment is used on the bones of the dead.', NULL, NULL, 'This is a simple and limited form of animate dead, except in this case the Necromancer can only manipulate the severed limbs of a corpse or skeleton. This means he can make one finger, hand, hand and forearm, arm, foot, or prehensile tail crawl or snake to him or do his bidding. This animated appendage can be used to frighten (H.F. 12) or distract people by skittering across the floor or a table, or made to retrieve a small object (key ring, knife, cup, jewelry, etc.), or to attack (grab a leg or throat, claw, punch, or stab, etc.). The animated appendage can also be used as an extension of the mage''s own hand. For example, the mage could hold an animated appendage such as a forearm and hand by the end of the forearm to touch, move, turn, grab, etc., something out of his normal reach. Skills that require manual dexterity are performed at -20% when a severed hand is used as an extension. - The number of appendages that can be animated at a time is limited to one per every two levels of experience, rounding up, so that''s one at levels 1 & 2, two at levels 3 & 4, three at levels 5 & 6, and so on. - Attacks/actions per melee round by the crawling bones are limited to three per round. - Damage by the appendage is 1D6 H.P./S.D.C. damage. - Speed is 15 for a hand or foot, 10 for all others. - Equivalent P.S. is 9. - Typical S.D.C. is as follows: Finger - 2 Hand - 12 Hand & Forearm - 24 Forearm only - 12 Upper Arm only - 15 Forearm and Upper Arm (no hand) - 27 Foot - 15 Foot & Lower Leg - 30 Lower Leg only - 15 Upper Leg (Femur) - 25 Tail (small/monkey) - 10 Tail (large) - 20', NULL, 'bone'),
  ('Bone: Fragile Bone to Wood', 2, 5, '5 points; 30 P.P.E. to make the transformation permanent.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.93', 'rifts', 'Touch or within 60 feet (18.3 m).', 'One hour per level of experience.', NULL, 'Not applicable, enchantment is used on the bones of the dead.', NULL, NULL, 'The Death Mage can turn the equivalent of one human-sized skeleton, or equivalent pile of bones (roughly 40 lbs/18 kg), from ordinary bone to the consistency of wood suitable for building. The "wood" bones are 20% stronger and heavier, so if the bone had 15 S.D.C. it now has 18 S.D.C. The wooden bones are a strong, reliable building material with properties nearly identical to wood. They can be nailed, lashed, glued, polished, sanded, etc., and used to make weapons, furniture, baskets, boats, doors, fences, gates, and even entire houses, although the latter is a rarity. Most Necromancers keep the original bone look for dramatic effect and personal preference (most Death Mages like the color and look of bones and skulls). Note: Ordinary bone and bone magically made into wood can be bent and molded via use of the Shape Bone spell in order to curve, bend, twist and adjust the shape of bones for use as building materials; ideal for shaping the handles of weapons, the legs for tables and chairs, pieces for head-wear, jewelry, and so on, as well as to get a consistent size, shape, look and symmetry. The temporary transformation of bone into wood is typically used on simple items when the strength of wood is helpful but long term use is not. For example, the mage might turn a bone to wood in order to use it as a cudgel/club that won''t shatter when it hits. Likewise, he might turn bones into wood to use as a brace or pole to jam a door open or closed, or to prop up a wagon to change a wheel, and so on. The Necromancer can also temporarily turn the bones of animated dead into wood, temporarily increasing their S.D.C. by 20% (See animated dead under Special O.C.C. Powers for details on animated skeletons). Bones are made into permanent wood for long term use.', NULL, 'bone'),
  ('Bone: Stench of the Dead', 2, 6, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.93', 'rifts', '100 feet (30.5 m) plus 10 feet (3 m) per level of experience.', '2 minutes per level of experience.', NULL, 'Standard', NULL, NULL, 'A magic mist covers the area when this spell is cast. The mist stinks of rotting meat and decay. The sickening smell causes all who enter its area of affect to cough and retch twice per melee round (15 seconds), plus the eyes water and no other odors can be smelled while in the overwhelming mist. Penalties: Reduce speed, number of attacks per melee and combat bonuses by half. The mist can be cast up to 100 feet (30.5 m) or further with experience.', NULL, 'bone'),
  ('Bone: Hide Among the Dead', 2, 5, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.93', 'rifts', 'Self or self and one other by touch.', 'Five minutes per level of experience.', NULL, 'None', NULL, NULL, 'Like the Chameleon spell, this magic allows the mage or one other to blend in with his background, only in this case, the background is limited to the remains of the dead. This means the Necromancer can hide among any types of corpses, skeletons, and even animated dead and appear to be just another corpse or skeleton. Even the most advanced modern medical and detection devices are fooled, as are magical and psionic means of detection (see aura, sense magic, presence sense, etc.). This magical concealment only works when there is at least one other corpse or skeleton, and if the Necromancer stays still. 98% undetectable if unmoving. 70% undetectable if moving two feet (0.6 m) per melee or slower. 20% undetectable if moving any faster. Yes, by the way, if the other bodies are removed (he''s the last one), the magic is destroyed and the mage will suddenly appear as his real, obviously living self ("How did we miss that guy?"). The same occurs if he is picked up and carried away from the other corpses. Level Three', NULL, 'bone'),
  ('Bone: Accelerated Decay', 3, 8, '8 per corpse or 200 pounds (90 kg) of organic material.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.94', 'rifts', 'Touch', 'Permanent results, with decay happen before one''s eyesing with each melee round (15 seconds) equal to the effects of one day of decay.', 'Decays the equivalent of two days per level of the spell caster. Fresh fish, prepared vegetables or fruit, stew, or any food prepared for consumption that day is inedible after the equivalent of two days of decay, fresh meat after four days, and fresh fruit and vegetables after the equivalent of six days. A fresh corpse can be turned to bits of flesh and bare bone after the equivalent of 60 days of decay. It is unrecognizable after 20 days, and stinks something terrible after four days. High level spell casters can regulate the level of decay in two day increments.', 'None, however if protected by a magic circle, sanctum spell, or against "spoiling," the food or deceased is impervious to this spell.', NULL, NULL, 'This magic accelerates the decaying process of organic material, from processed meat and prepared food to the body of a corpse. The level of decay and deterioration is equivalent to sitting in the hot sun (even if the actual food or corpse is refrigerated). An especially useful spell for covering up foul play by turning a fresh corpse into a withered husk. This means that investigators and pathologists are likely to overestimate the time of death by days and have trouble identifying the victim or have trouble determining the cause of death. The spell will also turn freshly prepared food, meat, cut fruit and vegetables into spoiled mush.', NULL, 'bone'),
  ('Bone: Object Read the Dead', 3, 8, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.94', 'rifts', 'Touch', 'Instant', NULL, 'None', NULL, NULL, 'This spell gives the character a power similar to the psionic ability of object read, only this power is limited to divining things about the dead. Information can be gathered from a corpse, animal carcass, skeleton, skull, or a single large bone. The data is limited but helpful: - General cause of death: old age, disease, plague, accident or murder. - Race or animal type. - Whether the creature suffered or not before dying. - Whether or not magic was involved. - The length of time the creature has been dead: immediate (a few minutes), recent (a few hours), quite a while (a few days), a long time (several months), years, or decades (over 20 years).', NULL, 'bone'),
  ('Bone: Recognize the Master', 3, 8, '8, or 30 P.P.E. to make the enchantment permanent.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.95', 'rifts', 'Within 10 feet (3 m) of the mage or by voice command of the mage within 100 feet (30.5 m).', 'One hour per level of experience, or permanent.', NULL, 'Not applicable, enchantment is used on the bones of the dead.', NULL, NULL, 'This feature is typically used in conjunction with permanent bone gates and doors. The spell enables the bone door, gate and any locking mechanisms built into it (even if the lock itself is not made of bone) to recognize the Necromancer who made it and to respond by opening and closing like a modern door with an electronic eye. It will not open to anybody but the Necromancer. To force open a normal door or gate, meaning it has no special key locks, sliding bolts on the inside or magical locking hands, one needs a combined P.S. of 20 or must break the door knob/handle (typically 15 S.D.C., or 4 M.D.C. if made of M.D.C. material). Once broken, the door can be pushed open with ease. If the Necromancer is within 100 feet (30.5 m), he can also command the enchanted bone doors or gates to automatically open and close whenever anybody approaches, but he can verbally rescind that order, effectively closing and locking all doors/gates under this enchantment. All doors under this enchantment will respond to the Necromancer''s voice commands.', NULL, 'bone'),
  ('Bone: Recognize the Undead', 3, 8, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.95', 'rifts', 'Self', '10 minutes per level of the Necromancer.', NULL, 'Standard', NULL, NULL, 'The spell caster is given the ability to instantly and automatically recognize all types of undead, including zombies, mummies, animated corpses, vampires and Vampire Intelligences, no matter how human or innocent they may appear. This knowledge enables the character to better prepare himself for conflict with these monsters (or to avoid such conflicts). Level Four', NULL, 'bone'),
  ('Bone: Command Ghouls', 4, 10, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.95', 'rifts', 'Self', '15 minutes per level of experience.', NULL, '-2', NULL, NULL, 'This incantation makes 2D4 ghouls per level of the spell caster''s experience fear and obey the necromancer. This spell will affect grave ghouls, the dybbuk and similar creatures, but has no affect on dimensional ghouls or ghoulish demon lords. Also note that the dybbuk doesn''t appreciate mind control and is likely to seek revenge on the person responsible, unless the mission was an enjoyable one. Grave ghouls are too timid to consider retribution.', NULL, 'bone'),
  ('Bone: Eyes of the Dead', 4, 8, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.95', 'rifts', 'Self', 'Five minutes per level of experience.', NULL, 'None for the user. Standard for victims.', NULL, NULL, 'With this enchantment, the eyes of the Necromancer become black and lifeless. Besides looking creepy and enhancing his already frightening appearance (+2 to Horror Factor), these dark eyes will protect the Necromancer from hypnotic suggestion and any mind control which involves eye contact. The enchantment also enables him to recognize ghouls, animated dead, and the undead. Furthermore, the necromancer''s own gaze will unnerve any who look into it, sending a chill running down his spine and a penalty of-1 to all combat skills for one melee round.', NULL, 'bone'),
  ('Bone: Funeral Dirge', 4, 6, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.95', 'rifts', 'Self or other by touch.', 'Five minutes per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'Note: Has no effect unless somebody has died, although it can be played for added affect during a Mock Funeral or as a warning. Upon recitation of this spell, the Necromancer (or another person, enchanted by touch) can play a recognizable mournful funeral dirge/death or funeral march on any type of horn, piano, drum, or string instrument. The music has foreboding and dark undertones and can be heard for one mile (1.6) per level of the spell caster. To ghouls, grave-robbers, demons, and other Necromancers and death cultists, it is sweet music that may mark the death of an enemy, and, to those creatures who feed on or use corpses, signals to them that a fresh corpse is available. All living creatures who hear it know that it marks the passing of a living being and may spark a moment of reflection and/or sorrow. Juicers, Crazies and Old Believers will feel so sad that they are -3 on initiative, -3 to strike, parry, and dodge, and -1 attack per melee round. These penalties remain in force while the music is played and for 2D6 minutes after it stops.', NULL, 'bone'),
  ('Bone: Kill Plants', 4, 10, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.95', 'rifts', 'Touch', 'Instant.', NULL, 'None, unless an intelligent life form, then standard. Millennium Trees are impervious to this spell.', NULL, NULL, 'This death touch inflicts !D4xlO S.D.C./Hit Point damage to plants per level of the spell caster''s experience. The killing touch is usually performed as an act of vandalism, vindictiveness, or cruelty.', NULL, 'bone'),
  ('Bone: Maggots (insects)', 4, 20, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.96', 'rifts', 'Touch', '2 days unless killed.', NULL, 'Standard', NULL, NULL, 'A destroying touch in which the Necromancer can touch food or a dead animal and infest it with maggots and worms that feed on the dead. If people act quickly they can kill the larvae and save 2D4x10% of the food by boiling, deep frying, smoking, microwaving and similar measures to kill the bugs and any possible disease.', NULL, 'bone'),
  ('Bone: Necro-Armor', 4, 16, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.96', 'rifts', 'Self or one other by touch.', 'One minute per level of the spell caster.', NULL, 'None for the user; onlookers must save vs a Horror Factor of 13. M.D.C. of the Armor: 13 points per level of the spell caster.', NULL, NULL, 'Within seconds, the character is covered with a mass of bones, skeletal fragments and putrid remains. This disgusting coating does not appear sturdy, but is, in fact, a barrier of Mega-Damage protection. Aside from that, the sight of this armor as it envelops its wearer is frightening to watch; roll to save vs Horror Factor 13. The armor also exudes a horrid stench, which will impair anyone within 100 feet (30.5 m) unless they have a separate oxygen supply, no sense of smell, or are supernatural predators. Penalties from the stench are -1 to all combat maneuvers (strike, parry, etc.). At the spell''s end, the armor sloughs right off and is quickly reabsorbed into the earth. If cast upon another person, the recipient must roll a successful saving throw vs Horror Factor 13 to fight without impairment. Failure means a penalty of -3 to all combat maneuvers for the duration of the armor.', NULL, 'bone'),
  ('Bone: Summon the Dead', 4, 10, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.96', 'rifts', 'One mile (1.6 km) radius per level of the spell caster.', '4D6x10 minutes.', NULL, 'None', NULL, NULL, 'This magic is similar to the Animate and Control Dead spell, except that this magic is more limited, because the spell caster doesn''t actually control the dead but brings the dead to him. This is especially useful when the Necromancer needs corpses in a hurry, but can''t take the time to go out and, um ... dig them up. 1D4 corpses/skeletons, +1 per every other level of experience, will rise from then- graves (or wherever) and march on a straight path to their summoner. This can take anywhere from a few minutes to a couple hours, depending on how far away the corpse is. Once the dead makes it over to the Necromancer, it collapses. To animate the thing further, the mage must use the Animate and Control Dead spell. Summon the Dead simply brings the dead to the Death Mage, exactly how he uses them later depends on the character. Alternately, the mage can elect to summon one specific dead to come to him. For this to work, the Necromancer must either have personally known the deceased or have a personal belonging, or sample of his or her blood, hair, or skin. This is often done to discover what has happened to a missing ally who is feared to be dead, or to desecrate a specific grave. Only one of the specific dead can be summoned in this manner, but the range is doubled. The same limitations as the general summoning still apply. Level Five', NULL, 'bone'),
  ('Bone: Consume Power & Knowledge', 5, 20, '20 per each item.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.96', 'rifts', 'Self', 'Varies.', NULL, 'Not applicable.', NULL, NULL, 'This repulsive magic requires that the necromancer remove the tongue, brain or organ of a dead being, boil or cook it while reciting the magic incantation, and breathe the fumes from the prepared meat. Necromancers who are monsters may tear out the organ and eat it raw (or cooked) with the same magic results. The basic concept behind this magic is the belief by many cultures, both human and monster, that eating the organs of one''s vanquished enemies will give the eater his courage or abilities. Different organs offer different powers. No powers are gained from animal organs. More than one item (maximum three) can be cooked up with accumulative effect. Heart: Courage and strength. The mage is +3 to save vs horror factor, is not easily unnerved or intimidated, gets an additional 10 S.D.C. and can lift and carry twice as much as normal. Duration: One hour per level of experience. Liver: Sobriety. No matter how much alcohol is consumed, the character cannot get drunk. Duration: One hour per level of experience. Kidneys: Impervious to poisons and +2 to save vs non-lethal drugs. Duration: One hour per level of experience. Intestines: Breathing the fumes provides physical nourishment. The character does not need to eat nor does he feel hungry for 48 hours. Tongue: Can understand and speak all languages. Duration: Two hours per level of experience. Eyes: The necromancer will recognize the people, places and items once known by the deceased. He will also know basic things about those people, places or items. For example, the necromancer will recognize the deceased''s friends, parents, family, lover, wife, enemy, murderer, home, favorite tavern, car, gun, clothes, etc. Duration: One hour per level of experience. Brains: Provides the mage with all of that person''s skills at 60% proficiency. Duration: One hour per level of experience.', NULL, 'bone'),
  ('Bone: Death Mask', 5, 12, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.96', 'rifts', 'Self', 'Four minutes per level of experience.', NULL, 'All who see the death mask must roll to save vs Horror Factor of 13.', NULL, NULL, 'The spell creates a frightening looking death mask that completely covers the spell caster''s face. The mask provides the following: - Disguises the character''s normal facial features. - Frightening visage evokes fear equal to a Horror Factor of 13. - Wearer is impervious to all normal disease, poisons, and magic sicknesses and curses. - Prowl at 55%', NULL, 'bone'),
  ('Bone: Divining Tombs & Graves', 5, 10, '10 or 35', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.97', 'rifts', 'Self', '5 minutes per level of the spell caster.', NULL, 'Standard', NULL, NULL, 'This magic requires the use of a wishbone from a large bird. The bone is held in both hands, vibrates and pulls the character in the direction of graves or tombs. When a grave has been located the wishbone stops vibrating. For the cost of an extra 25 P.P.E. the divining spell can locate a specific grave or tomb from among many.', NULL, 'bone'),
  ('Bone: Fragile Bone to Stone', 5, 10, '10 points; 60 P.P.E. to make the transformation permanent.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.97', 'rifts', 'Touch or within 60 feet (18.3 m).', 'One hour per level of the spell caster.', NULL, 'Not applicable, enchantment is used on the bones of the dead.', NULL, NULL, 'The Death Mage can turn the equivalent of one human-sized skeleton, or equivalent pile of bones (roughly 40 lbs/18 kg), from ordinary bone to the consistency of stone. The "stone" bones are twice as strong (double S.D.C.) and twice as heavy. Both ordinary bone and bones already permanently turned to wood (including those turned into weapons, furniture, doors, fences, and other items) can also be turned into stone. Real wood cannot. Additional P.P.E. will need to be expended to make larger bone items into stone. The Necromancer can also temporarily turn the bones of animated dead into stone, temporarily doubling their S.D.C. (roughly equivalent to two M.D.C.) and punch damage (becomes 2D6 S.D.C.), but weight is also doubled (approx. 80-100 lbs/36-45 kg depending on the size of the skeleton) and speed is reduced to 4 (See animated dead under Special O.C.C. Powers for details on animated skeletons). Note: Bones cannot be bent or shaped by the Shape Bone spell once they are turned into stone. Bones are made permanent for long term use.', NULL, 'bone'),
  ('Bone: Grip of Death', 5, 13, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.97', 'rifts', 'A 10 foot (3 m) diameter up to 100 feet (30.5 m) away.', 'Two minutes per level of experience.', NULL, 'Horror Factor of 13 and dodge of 16.', NULL, NULL, 'This magic causes 1D4+1 hands and arms of skeletons and corpses to erupt from the ground to grab and ensnare everybody in the radius of influence. First, each character in the area of affect must make a successful saving throw vs Horror Factor 13. A failed save will inhibit the character''s ability to dodge and is automatically ensnared by 1D4+1 of the hands risen from the grave (plus the usual penalties). Those who successfully save vs Horror Factor can attempt to dodge in order to escape the clutches of the flailing hands of the dead. The character must make two consecutive dodges of 16 or higher (uses up two melee attacks) to get out of the area of affect. If even one dodge is missed, the character is ensnared by 1D4+1 of the hands. Those ensnared are shook and pulled down on their knees, so they cannot simply ignore the clutching hands in an attempt to launch attacks at those outside the area of affect. Such attacks can be attempted but are done without benefit of any attribute, skill or combat bonuses - straight, unmodified die rolls. The same applies for trying to parry or dodge attacks leveled at them while in the Grip of Death! This penalty remains in effect the entire time the characters are trapped by this magic. Only a strength of 35 or higher (or supernatural P.S. of 20 or higher) can pull free of the hands, but one melee action is burned up for each hand that has a hold. Others can help in the effort, but they may also become ensnared by the hands from the grave as well. Chopping or blasting the grasping hand off at the base of the arm is another possibility but each arm has 13 M.D.C. and will use up the character''s melee attacks (the hand vanishes once destroyed). In either case, the character must then roll two consecutive dodges of 16 or higher in order to escape other hands of the dead trying to grab victims. Note: Negate Magic and Dispel Magic Barrier may offer a means to eradicate the entire magic spell. Anti-Magic Cloud automatically dispels it.', NULL, 'bone'),
  ('Bone: Locking Hand', 5, 10, '10 points per each locking hand; 30 P.P.E. per each to make the enchantment permanent.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.97', 'rifts', 'Touch or within 60 feet (18.3 m); not applicable when permanent.', 'One hour per level of experience or permanent.', NULL, 'Not applicable, enchantment is used on the bones of the dead.', NULL, NULL, 'The hand of a corpse or skeleton can be made to grab and hold tight with an equivalent P.S. of 24 (a P.S. of 25 or higher is needed to pry it open). This feature is typically used in conjunction with permanent bone gates and doors to be used as a locking mechanism or defense. As a lock, the hand automatically clenches onto a parallel bar or handhold as a tight, grasping fist to effectively lock/hold a door, gate, or grille shut. Anybody trying to pry the hand open will be clawed (2D6 S.D.C. damage) or grabbed and held until the Necromancer arrives. The hand opens when the mage who created it arrives, unless it is holding an intruder in its grasp, then it lets go only upon the command of the mage. When used strictly for defense, the hand (typically several hands or hands connected to a moveable forearm for an extended reach or leverage) will grab the intruder and hold him tight. If there are several hands, they will try to grab and hold each of the person''s arms and legs to prevent escape, and/or try to grab anybody who tries to free its captive or press forward with trying to open the door. Victims who have their hands/arms grabbed are helpless to pull free or perform any skills unless they have a P.S. of 25 or higher. Kicking and using the legs for leverage is of minimal value. If all appendages are held, the character is completely helpless. This locking feature can also be incorporated into chairs, thrones, beds, prison manacles, torture tables or sacrificial altars to hold victims in place and similar. Note: This enchantment can be used on skeletal hands that have been transformed into wood, stone or M.D.C. materials, provided the hand was once made of genuine bone. - P.S. of each hand is 24. - Magically Enhanced S.D.C.: Bone: 24, Wood: 48, Stone: 75, M.D.C.: 30. Level Six', NULL, 'bone'),
  ('Bone: Poison Touch', 6, 15, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.98', 'rifts', 'Self or one other by touch.', 'One minute per level of the spell caster.', NULL, '12 or higher, but victims are -2 to save.', NULL, NULL, 'This spell enables the touch of the Death Mage to secrete a dangerous poison that is transmitted by touch. Each touch requires a separate saving throw, and damage is accumulative. Bare skin must be available. Each touch inflicts 4D6 Hit Point/S.D.C. damage, unless the victim makes a successful save vs poison. A successful save means he suffers only 1D6 H.P. damage. A failed roll to save means the 4D6 damage plus the victim feels feverish, dizzy and nauseous (-1 on initiative, and reduce speed and skill performance by 30%; penalties linger for 1D6 minutes per each poisonous touch). The effects are immediate and cumulative. The magic Negate Poisons spell or potion will negate the symptoms and penalties, but not the damage inflicted. Those who are impervious to poison are not affected. Mega-Damage creatures only suffer one point of damage and -1 on initiative as they feel a little light headed, and suffer no effects on a successful save.', NULL, 'bone'),
  ('Bone: Wear the Face of Another', 6, 15, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.98', 'rifts', 'Self', 'One hour per level of the spell caster.', NULL, 'Not applicable, victim is dead.', NULL, NULL, 'This grotesque magic enables the Necromancer to quickly (30 seconds/two melee rounds) remove the skin from the face or entire head (including hair) from the skull of a corpse and magically adhere it to his own. The face of the dead man appears completely natural and alive, as if it were the mage''s real face. It can make for a completely undetectable physical disguise, unless somebody knows the deceased is dead. Of course the voice, memories, and body remain those of the Necromancer. Note: The corpse cannot have been dead for more than 24 hours. Level Seven', NULL, 'bone'),
  ('Bone: Curse: Death Wish', 7, 20, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.98', 'rifts', 'Touch or 10 feet (3 m) per level of the Necromancer.', 'One hour per level of the spell caster.', NULL, 'Standard, unless a willing subject, Juicer or Crazy, in which case the character is -3 to save.', NULL, NULL, 'Limitations: One victim per spell casting. This instills the recipient with no fear of death and suicidal tendencies that result in foolish, death-defying risk-taking, fights to the death, and unthinking courage. Unbeatable odds and overpowering opponents will not give them the least bit of hesitation. In fact, the victim will go out of his way to take unnecessary risks or challenge others to the point of making Juicers and Crazies look like sane and reasonable people. Speaking of Juicers and Crazies, their natural tendencies make them especially susceptible to this magic and are -3 to save. The enchantment gives those affected a bonus of +5 to save vs Horror Factor, +4 to save vs possession and mind control, and +2 on initiative, but it also gives them a penalty of -3 to parry, -6 to dodge, -6 to disarm, and -6 to roll with punch, fall or impact and have no bonuses to save vs coma/death. In fact, the victim rarely even attempts to dodge attacks, preferring to stand his ground against his opponents and fight like a man who doesn''t care whether he lives or dies. Level Eight', NULL, 'bone'),
  ('Bone: Death Bolt', 8, 30, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.98', 'rifts', '200 feet (61 m) +20 feet (6 m) per level of the Necromancer.', 'Instant, plus effects linger for one minute per level of the spell caster.', '1D6 damage direct to Hit Points per level of experience! If the opponent is supernatural or some other Mega-Damage creature, it suffers 1D6 M.D. per level of experience of the spell caster.', 'Special; potential victims are -2 to save, but cyborgs are +4 to save. Those who save take one third damage and suffer no penalties.', NULL, NULL, 'This magic unleashes a multi-tendrilled bolt of black lightning that erupts from the Death Mage''s palm and completely bypasses body armor (or natural A.R.) to inflict damage direct to the target. Damage is S.D.C. or M.D. depending on the nature of the victim. In addition, unless the victim rolls a successful save vs magic, he will suffer from the following penalties: -4 to initiative, -1 to parry and dodge, and Spd is reduced by 25% for one minute/four melee rounds. The bolt can pass through full environmental body armor and even light power armor, but not heavy power armor, medium to heavy Cyborg armor, walls, or heavy vehicles. It has no effect on robots or machines. Against undead creatures, the bolt has an energizing effect. Vampires, Dybbuk, Zombies, and all other sorts of undead will find its Hit Points or M.D.C. increased (or restored if injured) by 4D6 points the instant bolt the strikes it. Used repeatedly, a Necromancer mage can increase an undeads hit points or M.D.C. by a maximum of 60 points. The duration of the increased durability is two minutes per level of the spell caster, or until additional damage reduces it.', NULL, 'bone'),
  ('Bone: Death Strike', 8, 25, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.99', 'rifts', 'Self; melee attack directed at others.', 'One minute (four melee rounds) per level of experience.', NULL, 'Opponents are -1 to save.', NULL, NULL, 'Every punch, kick, or strike inflicted by bare hands/feet or by hand-held weapons such as a club or sword (excluding guns) inflicts double damage. Furthermore, if the opponent is a Mega-Damage being the doubled damage is Mega-Damage!', NULL, 'bone'),
  ('Bone: Fragile Bone to M.D.C. Bone', 8, 40, '40 points; 160 P.P.E. to make the transformation permanent.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.99', 'rifts', 'Touch or within 60 feet (18.3 m).', '30 minutes per level of experience.', NULL, 'Not applicable; the enchantment is used on the bones of the dead.', NULL, NULL, 'The Death Mage can turn one human-sized skeleton, or equivalent pile of bones, from fragile bone (or permanent wood bone) to Mega-Damage materials! If the bone had 15 S.D.C., it now has 15 M.D.C., if it is an entire animated skeleton, the thing is now an M.D.C. skeleton (S.D.C. converted to M.D.C.). See animated dead under Special O.C.C. Powers for details on animated skeletons. Necromancers sometimes make a suit of armor, weapons, furnishings or decorations out of bone and then permanently transform them into Mega-Damage Structures - has the light weight of bone, but Mega-Damage resilience. 22 M.D.C. for armor that covers chest and shoulders only (weighs 15 lbs/6.8 kg), 22 M.D.C. for skull helmet (weighs 5-8 lbs/2.3 to 3.6 kg), 45 M.D.C. for a half-suit and helmet that protects the upper body, arms and head (weighs 22 lbs/10 kg), and 80 M.D.C. for a full body suit made predominately from bones and/or the exoskeleton of alien beings. The full suit may incorporate padding and other, non-bone materials. Average weight is 40 Ibs (18 kg). Note: Additional P.P.E. may be needed to make M.D.C. armor or to turn larger quantities of bone into M.D.C. material. One or more blood sacrifices are often needed to acquire the necessary amount of P.P.E. Bones cannot be bent or shaped by the Shape Bone spell once they are turned into M.D.C. material, and this magic can only be used on ordinary bone or bone transformed to wood, not stone.', NULL, 'bone'),
  ('Bone: Mock Funeral (curse)', 8, 40, '40 for one individual, +20 for each additional member of a group or family included in the curse.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.99', 'rifts', 'Line of vision.', '24 hours +12 hours per level of the Necromancer, starting with level two.', NULL, '16 +1 per every three levels of the Necromancer''s experience, so if the Death Mage is 3rd level, potential victims must roll a 17, if 6th level they need 18, at 9th level they need 19, and if 12th level or higher they need to roll either a natural 20 or 21 or higher with bonuses.', NULL, NULL, 'A powerful method of unnerving (sometimes frightening away) an enemy by placing a "death curse" on the individual and leaving a coffin with his effigy as a warning. This ritual magic involves making an effigy (often a scarecrow) of the character to be cursed and the participants (Necromancer and at least one other person) wailing, mocking, cursing, laughing and scoffing at the individual, group or family characterized by the effigy. In the case of cursing an entire group or family (six people maximum), the effigy is the head of the family or group with small rag dolls laid in the coffin with him or her to signify each family or group member. The person(s) being "laid to rest" in effigy must, at some point, see himself in the coffin for the magic curse to work. To this end, the coffin is left in some obvious, often unavoidable place, like an entrance way, doorway, front room, bedroom, in or on top of a vehicle, etc. If the coffin is spied from a distance, the characters) is inexorably drawn to it to see who is inside. The coffin can be elaborate and fancy or a simple wooden box (typically the latter). Note: This death curse is especially dangerous and effective, because the Necromancer who inflicted it knows exactly what his victim''s (temporary) fears and weaknesses are, and will exploit them. So if the character is vulnerable to poison or fire, the mage or his henchmen will use that against him. Likewise, if vulnerable to a particular creature, like a water spirit, fire demon, dragon, etc., the villain will try to pit one or more against the character. These curses are designed specifically to intimidate, terrify and undermine the Necromancer''s enemies. Types of Mock Funerals & their Curses If the coffin is filled with dirt, the cursed individual will feel trapped, pressed upon, buried by responsibility and worry. All skills are performed at -20% and initiative is -2. If the effigy is torn or chopped apart, the cursed character will feel lost and confused. Sense of direction/land navigation and navigation skills are -70%, all other skills are -10%; becomes easily lost even in familiar surroundings. If the effigy is holding a dagger & blood stains run down from the mouth/lips, the cursed character suffers from a Death Wish, same as the spell described under 7th level Necro-Magic, only for the longer duration that comes from a Mock Funeral ritual curse. If burned, the cursed individual will suffer double damage from fire. If a metal spike is driven into the chest, the cursed individual will suffer double damage from lightning and electricity. If laid upon or wrapped in a banner of one the Warlords, Sovietski, or other power, the individual will be hounded by members of that group - wanted dead or alive for crimes he may or may not have committed. The latter will require the Necromancer having false accusations made against the individual or frame him for something he didn''t do. If filled with snakes, the cursed individual cannot save vs poison and suffers double damage from poison, plus he is -1 to save vs magic cast by dragons. If filled with rats or mice (dead or alive), the cursed individual cannot save vs disease and suffers double damage from illness. If drowned (the casket is either filled with water or dumped in water - river, lake, pond, pool, etc.), the cursed character forgets how to swim, making him vulnerable to drowning, and water based attacks by water demons, water spirits and water elementals do double damage. If the casket is overturned and the effigy is dumped onto the ground, the cursed individual cannot save vs punch, fall or impact and takes full damage from such attacks, including explosions. Furthermore, the character is -50% on the skills climb, acrobatics and gymnastics. If left on a doorstep, or wherever the character is currently living or an establishment he/she frequents, it is a warning that the individual or family is marked (usually by a Necromancer or his friends or associates), and that the individual or family member must cease his activities against them or be destroyed. Often a note will be attached to the effigy to clarify exactly whom should be left alone. Level Nine', NULL, 'bone'),
  ('Bone: Curse of Hunger', 9, 50, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.100', 'rifts', 'Touch or 10 feet (3 m).', '24 hours per level of experience.', NULL, 'Standard', NULL, NULL, 'This magic instills an unreasoning feeling of hunger in its victim, similar to the Starvation Touch of the Horseman of the Apocalypse, Famine. The feeling of hunger is so strong that even when stuffed to the gills, the victim will think of nothing but eating. While hungry, the victim is -2 on initiative and all combat abilities. After eating, he will be fine for the next 2D6 minutes, but will quickly become hungry again. If he eats again when he''s already full, he will become extremely sick and vomit 1D4 times in the next twenty minutes. Penalties are the same as when hungry, except that vomiting will fully impair the victim for one melee round (15 seconds); this means only one melee action and no combat bonuses (the act of vomiting takes up all other melee actions that round). Supernatural creatures and creatures of magic are immune to the effects of the spell.', NULL, 'bone'),
  ('Bone: Death''s Embrace', 9, 35, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.100', 'rifts', 'Touch or up to 30 feet (12.2 m) per level of experience; line of sight.', 'Effects last for 1D6 minutes per level of the spell caster.', 'Special', 'Standard saving throw vs magic, however, psychics with sensitive powers are -2 to save.', NULL, NULL, 'A powerful force of arcane energies is summoned and directed toward one particular living target. The energies are take the form of a black, ghostly apparition that swirls around and embraces the victim. For the duration of the spell, the apparition softly weeps and moans. The effect is that the character embraced by the thing feels defeated and lost to the point that he simply stands or sits, unable to take any initiative whatsoever. The victim will not attack, perform skills, or even shout a warning to a friend. The only action he can take is in self-defense. Once gone or dispelled, the character instantly snaps out of his stupor and takes action. Note: This debilitating energy can be dispelled by sorcerers via Negate Magic, Dispel Magic Barrier, and Reality Flux.', NULL, 'bone'),
  ('Bone: Funeral Pyre', 9, 35, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.100', 'rifts', '20 foot (6.1 m) radius per level of the spell caster.', '1D4 minutes', NULL, 'None', NULL, NULL, 'This spell causes all corpses and dead bodies within range to burst into flame, and only those quickly doused with a vial of holy water or embraced (held) by the living will not be consumed. After 1D4 minutes, the remains will be burnt down to a pile of bones. This is very useful for cleaning up after a big battle or destroying evidence of a slaughter, although the surviving skeletons will raise questions. Note: This spell has no affect on animated dead, mummies, zombies, or the undead.', NULL, 'bone'),
  ('Bone: Greater Animated Dead', 9, 50, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.100', 'rifts', '800 feet (244 m); line of vision.', '10 minutes per level of experience.', NULL, 'None', NULL, NULL, 'Virtually identical to the Animate and Control Dead spell, except the range and duration are all doubled (as noted above), the number of dead one can animate is doubled (4), and the animated dead are twice as fast (spd 14). They are also stronger (P.S. 20; inflicting 2D6+5 S.D.C./H.P. damage), have 50% more S.D.C. (75-210 depending on size) and each has four attacks per melee round (instead of two).', NULL, 'bone'),
  ('Bone: Shadows of Death', 9, 45, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.100', 'rifts', 'Self or 20 feet (6 m)', '24 hours per level of experience.', NULL, 'Standard', NULL, NULL, 'This spell creates strange and monstrous shadows but has two different applications. If cast on himself, the Necromancer''s own shadow will seem to have a life of its own, move independent of the mage, make sudden or threatening movements, and generally look frightening and unnatural. This adds +2 to the horror factor of the mage and makes opponents -2 on all combat bonuses because the movements of the shadow are startling and distracting. Alternately, the shadows of death can be cast on others. In this case, the spell is considered a curse. Victims have a constant feeling that they are being watched and/or in danger. They constantly catch glimpses of movement and strange shadows from the corners of their eyes. This makes the character paranoid and jumpy, plus they have trouble sleeping. Penalties: Tired from lack of sleep and constantly being on edge, reduce speed and endurance/fatigue levels by 20% and all combat bonuses are -1.', NULL, 'bone'),
  ('Bone: Shadow of Doom (curse)', 9, 45, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.101', 'rifts', 'Touch or 20 feet (6 m)', '48 hours per level of experience.', NULL, 'Standard', NULL, NULL, 'This spell should be considered a magic curse. The cursed character is depressed and feels like the sword of doom is about to drop on him. Penalties: -2 on initiative, -1 on all other combat bonuses and -20% on all skill proficiencies. Level Ten', NULL, 'bone'),
  ('Bone: Command Vampires', 10, 100, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.101', 'rifts', 'Self and 50 feet (15.2 m) per level of experience', 'One hour per level of experience or less', NULL, 'Special', NULL, NULL, 'This spell imbues the spell caster with the ability to impose his will over vampires as if he were a Master Vampire of the same level of experience. Effects are identical to the Mind Control: Vampire over Vampire ability listed on pages 21-22 of Rifts World Book One: Vampire Kingdoms, except that only one vampire per level of experience can be controlled this way. Only Wild and young Secondary Vampires are affected. Masters, Ancient Secondary Vampires, and, of course, the Vampire Intelligences, are immune. As stated in Vampire Kingdoms, a Secondary Vampire that fails to resist will remain under control for 1D4 hours. A Wild Vampire will remain subservient for 2D6 hours. After the time period elapses, the vampire can try again to resist the mind control. Should a vampire manage to resist or otherwise break free of the mind control, it can attack the Death Mage, but not necessarily. Vampires are evil creatures who like doing evil, so they may enjoy the tasks that are asked of them while under the Necromancer''s influence. They may even volunteer to assist the Necromancer in his evil tasks after the spell elapses (this won''t happen if the mage abuses or tortures the creatures or fellow undead). Otherwise, the mage can keep trying to enforce his will over vampires for one hour per level of his experience or until an hour before sunrise. Vampires do need their sleep, after all.', NULL, 'bone'),
  ('Bone: Curse of Wasting', 10, 80, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.101', 'rifts', 'Touch or 10 feet (3 m).', '24 hours per level of experience.', NULL, 'Standard', NULL, NULL, 'No matter how much the victim eats, his body begins to waste away as if he hasn''t eaten in days. After 24 hours the victim''s eyes are sunken and grey, the body unnaturally thin and sickly looking and the character feels tired and weak. P.S., P.P., Spd and attacks per melee round are all reduced to half (also reduce any attribute bonuses appropriately). In addition, skill performance is -20%. The character gets thinner and weaker with each passing day, reduce the following every 24 hours: -1 on all combat maneuvers (initiative, strike, parry, etc.), -1 on all saving throws, -10% on skill performance, -1 on Spd; all penalties are cumulative. Supernatural creatures and creatures of magic can also be affected by the curse, but only for two hours per level of the spell caster''s experience (so only the initial penalties appear after one hour). Vampires and other undead are not affected.', NULL, 'bone'),
  ('Bone: Strength of the Dead', 10, 60, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.102', 'rifts', 'Self, must touch the dead creature.', '2 minutes per level of experience.', NULL, 'None', NULL, NULL, 'Temporarily draws and gives to the Necromancer half the S.D.C. and Hit Points (or M.D.C. if a mega-damage creature!) that the creature had while it was alive!', NULL, 'bone'),
  ('Bone: Summon Insect Swarm', 10, 80, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.102', 'rifts', '1000 miles (1600 km)', '12 hours per level of experience.', NULL, 'None', NULL, NULL, 'This ritual magic will cause 1000 flying insects (per each level of experience of the summoner) to amass in a gigantic, blinding cloud. The swarm covers a 100 foot (30.5 m) radius per level of the Necromancer. Blinding cloud of flying insects: Thousands of flying insects fill the air as a massive, living cloud. The swarm interferes with accurate radar readings, creating false readings, and reduces visibility to about 10 feet (3 m). The bugs are also very distracting, noisy and annoying, covering or splattering themselves on windshields and visors, impairing vision even more. The insect swarm may also clog engines, air intake valves, vents, and joints of bots, borgs and vehicles, causing varying damage and problems, such as engines overheating, cutting off air supplies, etc. Characters not protected inside environmental body armor, power armor or a vehicle will be pelted and covered by the bugs. Even though most of the insects in this swarm are harmless, they will crawl in the ears and nose, fly into the mouth and eyes, crawl under clothes and so on. The overall sensation is disgusting and debilitating. Penalties: Characters caught in the cloud lose half of their melee actions, can barely see or hear, completely lose initiative and all combat bonuses, and speed is reduced by half. Level Eleven', NULL, 'bone'),
  ('Bone: Bone Scepter', 11, 160, '160 points; creates a permanent magic item.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.102', 'rifts', 'As per spell or as melee weapon.', 'As per spell (3rd level potency) or until destroyed.', NULL, 'As per spell.', NULL, NULL, 'Typically a scepter or rod made entirely of bone and which ends with a skull, skeletal jaw with teem, or hand, claw or taloned foot (bird-like). The permanent enchantment turns it into a low-powered magic weapon with the powers to cast three different spells once each per 24 hours: Select three from the following: Repel Animals Fear Negate Poison Spoil Turn Dead Sickness It is considered a magic weapon with 50 M.D.C. (on S.D.C. worlds it has 500 S.D.C.). The weapon suffers damage only when an adversary deliberately tries to destroy it by direct attacks at the weapon only. When used as a blunt weapon it inflicts 3D6 H.P./S.D.C. damage to mortal S.D.C. beings and 2D6 M.D. to demons and other Mega-Damage creatures, including those clad in full M.D.C. body armor, cyborgs and robots.', NULL, 'bone'),
  ('Bone: Bone of Invisibility', 11, 180, '180; creates a permanent magic item.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.102', 'rifts', 'Wearer or holder; must be worn or held in one''s hand to be effective.', '15 minutes. The bone is so empowered until it is destroyed.', NULL, 'As per spell.', NULL, NULL, 'Note: Requires one single, small bone from a rat. Typically a small enchanted bone that fits in the palm of the hand or worn as a simple necklace. This bone can turn the holder/wearer invisible as often as six times per 24 hours. To activate its magic, the user must close his hand around it and say, "make me invisible." This magic item has 30 M.D.C. (on S.D.C. worlds it has 300 S.D.C.), but only suffers damage when an adversary deliberately tries to destroy it by directing his attacks at it only.', NULL, 'bone'),
  ('Bone: Summon Vampire', 11, 150, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.102', 'rifts', '1000 miles (1600 km)', '24 hours per level of experience.', NULL, 'None', NULL, NULL, 'This ritual magic will cause 1D4 vampires within a 1000 mile (1600 km) radius to come to the Necromancer within 12 hours (at night, of course). If there are no vampires in the area, none will come. Only wild vampires and/or secondary vampires must heed the mystic summons. The master vampire and old secondary vampires are not affected. Most vampire(s) see the Necromancer as a kindred spirit and a potential ally, so they will gladly work with the death mage. The magic requires the undead to stay for 24 hours per level of experience of the summoner. However, they can decide to stay longer if that is what they desire, the only difference is the vampire is no longer obligated to obey the Necromancer. This means a free vampire may continue to work with the sorcerer, especially if there is a lot of bloodshed or if the creature likes the mage''s scheme. Otherwise, the vampire is free to do as he pleases.', NULL, 'bone'),
  ('Bone: Transfer Life Force', 11, 150, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.102', 'rifts', '10 feet(3 m) per level of experience.', '24 hours per level of the spell caster.', NULL, 'None', NULL, NULL, 'This spell enables the Necromancer''s life essence to inhabit and animate skeletons, corpses, mummies, zombies and even puppets, like a robot. The possessed dead thing has all the mental and physical powers of the Necromancer, however magic spells and psionic powers cannot be used, because the corpse hasnoP.P.E. orl.S.P.! The body is dead so it is impervious to pain, hunger, thirst, fatigue, disease, drugs, poisons, gases, heat and cold. However, the sense of smell is lost and the sense of touch is about half of normal. Vision and hearing are provided by mystic means. If the body is destroyed, it is no big deal, the spell caster simply returns to his real living body and can always inhabit another dead body if so desired. The spell can be used as an offensive measure or a subtle means to spy or confuse. The spell caster can disguise himself completely by inhabiting a recently deceased individual or conceal his identity by inhabiting a corpse or skeleton. Note: The dead body looks ... well... dead and continues to discolor and decay. After a while, the dead body will smell pretty terrible and parts may drop off. Level Twelve', NULL, 'bone'),
  ('Bone: Bone Staff', 12, 210, '210 points; create permanent a permanent magic item.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.103', 'rifts', 'As per spell or as melee weapon.', 'As per spell (3rd level potency) or until destroyed.', NULL, 'As per spell.', NULL, NULL, 'A staff made entirely of bones. It may have a skeletal jaw with teeth, one or more skulls, hands, claws, taloned foot, horns, giant teeth, or feathers at the top or on each end. The permanent enchantment turns it into a low-powered magic weapon with the powers to turn the dead (equal to a 3rd level spell), hold vampires at bay as if it were a holy symbol and inflicts double damage to animated dead - corpses, skeletons, crawling hands, and mummies (but not the undead or zombies). It is considered a magic weapon with 80 M.D.C. (on S.D.C. worlds it has 800 S.D.C.). The weapon suffers damage only when an adversary deliberately tries to destroy it by directing his attacks at the weapon only. When used as a blunt weapon it inflicts 4D6 H.P./S.D.C. damage to mortal S.D.C. beings and 3D6 M.D. to demons and other Mega-Damage creatures, including those clad in full M.D.C. body armor, cyborgs and robots.', NULL, 'bone'),
  ('Bone: Necklace of Bat Skulls', 12, 290, '290; creates a permanent magic item.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.103', 'rifts', 'Wearer; must be worn to be effective. Can be worn as a necklace or bracelet.', 'The necklace is so empowered until it is destroyed.', NULL, 'As per spell.', NULL, NULL, 'Note: Must have at least four skulls. An amulet that gives the wearer perfect hearing (+1 on initiative) and enables him to see in non-magical darkness (nightvision 200 feet/61 m) as long as the item is worn. The amulet is considered a magic item with 50 M.D.C. (on S.D.C. worlds it has 500 S.D.C.), but only suffers damage when an adversary deliberately tries to destroy it by directing his attacks at it only.', NULL, 'bone'),
  ('Bone: Necklace of Bird Skulls', 12, 290, '290; creates a permanent magic item.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.103', 'rifts', 'Wearer; must be worn to be effective. Can be worn as a necklace or bracelet.', 'The necklace is so empowered until it is destroyed.', NULL, 'As per spell.', NULL, NULL, 'Note: Must have at least four skulls. An amulet of clear sight that gives the wearer perfect 20/20 vision (no need for eyeglasses) and exceptional long-distance vision, plus enables him to see into the ultraviolet spectrum of light as long as the item is worn. The amulet is considered a magic item with 50 M.D.C. (on S.D.C. worlds it has 500 S.D.C.), but only suffers damage when an adversary deliberately tries to destroy it by directing his attacks at it only.', NULL, 'bone'),
  ('Bone: Necklace of Dragon Teeth', 12, 320, '320; creates a permanent magic item.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.103', 'rifts', 'Wearer; must be worn to be effective. Can be worn as a necklace or bracelet.', 'The necklace is so empowered until it is destroyed.', NULL, 'As per spell.', NULL, NULL, 'Note: Must have at least three teeth. An amulet of clear sight that gives the wearer the ability to see the invisible as long as it is worn or held in one''s closed hand. The amulet is considered a magic item with 80 M.D.C. (on S.D.C. worlds it has 800 S.D.C.), but only suffers damage when an adversary deliberately tries to destroy it by directing his attacks at it only.', NULL, 'bone'),
  ('Bone: Necklace of Snake Skulls', 12, 300, '300; creates a permanent magic item.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.103', 'rifts', 'Wearer; must be worn to be effective. Can be worn as a necklace or bracelet.', 'The necklace is so empowered until it is destroyed.', NULL, 'As per spell.', NULL, NULL, 'Note: Must have at least four skulls. An amulet of healing and protective magic that makes the wearer impervious to disease that causes fever, snake bites, and poison, plus provides a +2 bonus to save vs all types of magical illnesses. The amulet is considered a magic item with 50 M.D.C. (on S.D.C. worlds it has 500 S.D.C.), but only suffers damage when an adversary deliberately tries to destroy it by directing his attacks at it only.', NULL, 'bone'),
  ('Bone: Summon Worms of Taut', 12, 210, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.103', 'rifts', 'Not applicable', '24 hours per level of experience.', NULL, 'Standard', NULL, NULL, 'This ritual plucks one or more demonic worms of Taut from its native dimension and magically places it before the summoning Necromancer. The creature is automatically under the spell caster''s control and will obey him without question. Not all worms can be summoned, only the Nippers, Fire Worms and Tomb Worms. As many as one per level of experience can be summoned. The problem with this spell is that after the duration time has elapsed, the necromancer''s control over the worms is gone but they remain. All Worms of Taut are extremely aggressive and dangerous predators. See Rifts Conversion Book or Palladium''s Monsters & Animals for descriptions. Level Thirteen', NULL, 'bone'),
  ('Bone: Skull with Flaming Eyes', 13, 300, '300 points; creates a permanent magic item.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.104', 'rifts', '300 feet (91 m) as a lantern, or by touch.', 'Will function indefinitely or until destroyed.', NULL, 'As per spell.', NULL, NULL, 'A magical creation that permanently enchants the skull of a human or other intelligent creature with the powers of light, warmth and fire. It is considered a magic item with 100 M.D.C. (on S.D.C. worlds it has 1000 S.D.C.). The skull suffers damage only when an adversary deliberately tries to destroy it by directing his attacks at it only. - Flaming eyes that provide light like a lantern and which can fire beams of light like a high-powered flashlight or lantern; 300 foot (91.5m) range. - The light from the eyes magically extinguishes during the day and in brightly lit rooms, and automatically appears with the coming of dusk or in darkness. - The flaming eye sockets burn like hot coals and can be used to light wicks or branches to build a fire by placing one end of the item into the glowing eye socket. Putting a finger into the eye socket will bum, inflicting 3D6 H.P./S.D.C. damage and setting any flammable items (like gloves) on fire; 1D6 M.D. to angels/Spirits of Light, Faerie Folk, Elementals and spirits. - Provides warmth equal to a large campfire or fireplace. - Skull can fire Bolts of Fire six times per 24 hours: 5D6 M.D., double damage to angels/Spirits of Light, Faerie Folk, Elementals and spirits; range: 300 feet (91 m).', NULL, 'bone'),
  ('Bone: Skull of Knowledge', 13, 320, '320 points; creates a permanent magic item.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.104', 'rifts', 'As per spell; range of vision is 1000 feet (305 m).', 'As per spell (3rd level potency) or until destroyed.', NULL, 'As per spell.', NULL, NULL, 'Each of the following magic spells or abilities can be performed once per 24 hours and the skull relates/speaks about what it has seen or learned. All spells are equal to 3rd level in potency and duration, non-magical abilities are limited to 30 minutes. See the Invisible See Aura Second Sight EyesofThoth Cipher: Count & perform basic mathematical calculations 98% Identify plants and fruit 98%. Translate for one particular language 90% Note: The skull itself can understand and speak all languages at all times at 90% proficiency, and responds in the language by which it was addressed. The skull never speaks or does its magic without being addressed with the opening words, "O* Skull of Knowledge, tell me ..." whatever - "what invisible beings you spy," "what words you read," "what of my future can you see," etc.', NULL, 'bone'),
  ('Bone: Necklace of Goblin Skulls', 13, 340, '340; creates a permanent magic item.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.104', 'rifts', 'Wearer; must be worn to be effective. Can be worn as a necklace or bracelet.', 'The necklace is so empowered until it is destroyed.', NULL, 'As per spell.', NULL, NULL, 'Note: Must have at least two skulls. A macabre amulet that gives the wearer the ability to understand and speak Gobblely and Faerie Speak, as well as nightvision (100 feet/30.5 m) as long as the item is worn. The amulet is considered a magic item with 50 M.D.C. (on S.D.C. worlds it has 500 S.D.C.), but only suffers damage when an adversary deliberately tries to destroy it by directing his attacks at it only.', NULL, 'bone'),
  ('Bone: Curse: To Hell & Back', 13, 180, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.104', 'rifts', 'Touch or up to 10 feet (3 m).', 'One melee round (15 seconds) for the initial voyage to hell, but the effects linger for one hour per level of the spell caster.', NULL, '-1 to save vs magic.', NULL, NULL, 'Unless the targeted individual rolls a successful save vs magic, this spell sends him on a mental and emotional trip through the darkest comers of his mind. In a span of only a few seconds, the victim will re-experience every loss he has ever felt and every injury he has ever inflicted. During this mental assault, the character is oblivious to everything around him and cannot take any action. The experience is humbling to even the strongest spirit and shattering to all others. After this moment of torture, vestiges of the experience will continue to haunt the victim for up to one hour per level of the spell caster. The effects are half for those with an M.E. attribute of 20 or higher. For the duration of this haunting, the victim is obviously shaken and emotionally feeble. During this period, the character is distracted and despondent. If nothing demands his immediate attention, the character will want to curl up into the fetal position and be left alone. The victim suffers from emotional shell-shock with the following penalties: -6 to initiative, -4 to parry and dodge, -6 to save vs Horror Factor, and -4 to save vs mind control. In addition, the speed attribute, skill performance, and attacks per melee are reduced by half, and only one offensive move can be taken per round, all others are defensive only. Even 1D4 days after the experience, the victim will be -1 on initiative.', NULL, 'bone'),
  ('Bone: Summon Magot (monster)', 13, 320, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.105', 'rifts', 'Not applicable', '12 hours per level of experience.', NULL, 'Standard', NULL, NULL, 'This impressive ritual actually plucks one hideous Magot demon from its native dimension and magically places it before the summoning necromancer to do his bidding. The Magot is automatically under the spell caster''s control and will obey him without question. The creature''s time on Earth is limited and it warps out after the duration time of the summoning magic elapses, or when the summoner bids it to leave, or when it is slain. The Average Magot M.D.C.: !D4xlOOO Horror Factor: 13 Attacks per Melee Round: 8 Damage: 4D6 M.D. swat with eye stalk, 6D6 M.D. punch, or 2D6x10 M.D. bite. Each of the three eye stalks fire a beam that causes temporary petrification for 3D6+2 minutes. Victims need a 13 or higher to save. Magic & Psionics: None Notes: Average I.Q. 5, P.S. 43, Spd 90, 20 feet (6 m) tall. See Rifts Conversion Book pages 214 & 215 for complete details. Level Fourteen', NULL, 'bone'),
  ('Bone: Return from the Grave', 14, 60, 'Special; a total of 60 P.P.E. and 24 hit points are permanently spent.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.105', 'rifts', 'Self only', 'Special', NULL, 'None', NULL, NULL, 'This magic is less of a ritual and more like a full-time commitment. One evening, once a week, before going to rest, the Necromancer must conduct a ritual which requires reciting a series of arcane verses, ceremonial bloodletting (human or large animal sacrifice), and the temporary expenditure of 25 P.P.E. by the mage. Furthermore, an involved ritual must be conducted every full moon, during which the mage permanently sacrifices three P.P.E. and two Hit Points. After a full year of conducting both rituals, the magic is complete and the Necromancer must only recite a mantra every night. The purpose of the magic is not obvious at first. But when its effects are realized, they are very apparent. If the year-long ritual is done properly, without missing any of the nightly rituals (if so, P.P.E. and H.P. expended are lost; start again), it will enable the Death Mage to "return from the grave" as a member of the undead. The willing subject of this magic will forever walk the Earth as a vampire, at least until someone destroys him. He is very powerful, thoroughly evil, and even more dedicated to death than before. This magic is one of the only ways for someone to become a member of the undead (equal to a Master Vampire) without being reliant on some other source of power, such as a Vampire Intelligence. Note: Supernatural creatures and creatures of magic, like dragons, cannot use this magic, but mortals and D-Bees can. The basic powers and weaknesses of this creature are as follows: - Hit points are equal to twice the amount of the Necromancer''s base P.P.E. at the time of his death. They do not increase with further experience as an undead, since it is locked at the highest level he had attained before death. - P.S. attribute is increased to 26 or +4, whichever is higher, and is considered to be supernatural. - P.P. and Spd are identical to what the mage had during his life. - P.E. is no longer applicable as the creature never tires and is immune to poisons, disease, cold and many forms of magic. - P.B. attribute is reduced to 1D6. - All mental attributes are reduced by -1D4. - Horror Factor is 3, plus one per level of experience he achieved in life. - Attacks per melee are four, plus one for every four levels of experience in life. - New combat bonuses are +3 to initiative, +4 to strike and parry, +2 to dodge, +3 to roll with punch/impact, +1 to entangle, and +2 to disarm, in addition to any P.S. or P.P. attribute bonuses. - The powers of necromancy remain, but in a diminished capacity. All Special Abilities & Powers of the Necromancer O.C.C. (1-5) remain intact, but O.C.C. bonuses do not apply. Furthermore, the Death Mage''s usual P.P.E. level is reduced by half, making spell casting limited. Moreover, reborn as a vampire, the character only turns to magic when it amuses him or when desperate, otherwise the character relies on his vampiric abilities. - Half the O.C.C., O.C.C. Related and Secondary skills the mage knew in life are retained, the others are forgotten. All skills that remain are permanently frozen at the level they were at the time of death. Summary of natural Vampire combat abilities (as they apply to undead created by this sorcery): The undead creature is no longer vulnerable to normal weapons. Only magic, psionics, wood or silver weapons and physical attacks or strikes from a supernatural creature will inflict damage to the undead. In addition, weapons made of or plated with silver (the bane of all undead) inflict double damage. Damage is regenerated at the rate of 1D6 Hit Points per melee round. The undead creature can function even if reduced to -20 Hit Points, albeit at half speed. Even when reduced to -40 Hit Points, he will be immobile/comatose, but will survive, recover 1D6 H.P. per melee round, regaining consciousness at zero. Otherwise, the Undead Necromancer has all the basic abilities, bloodlust and desires of a classic vampire (see Rifts Vampire Kingdoms for details). The only way to permanently destroy the creature is the same way as to kill a vampire.', NULL, 'bone');

-- Read the result back.
SELECT 'bone spells inserted' AS assertion, count(*) AS got, 59 AS want
  FROM spells WHERE tradition = 'bone';

SELECT 'every one is prefixed' AS assertion, count(*) AS got, 59 AS want
  FROM spells WHERE tradition = 'bone' AND name LIKE 'Bone: %';

SELECT 'every one cites this book by page' AS assertion, count(*) AS got, 59 AS want
  FROM spells WHERE tradition = 'bone' AND source_book LIKE 'Rifts World Book 18: Mystic Russia p.%';

SELECT 'every one carries a cost' AS assertion, count(*) AS got, 59 AS want
  FROM spells WHERE tradition = 'bone' AND ppe > 0;

SELECT 'every one carries a description' AS assertion, count(*) AS got, 59 AS want
  FROM spells WHERE tradition = 'bone' AND length(description) > 40;

SELECT 'the schedules carry their note' AS assertion, count(*) AS got, 23 AS want
  FROM spells WHERE tradition = 'bone' AND ppe_note IS NOT NULL;

SELECT 'all fourteen levels are represented' AS assertion, count(DISTINCT level) AS got, 14 AS want
  FROM spells WHERE tradition = 'bone';

-- A CROSS-BATCH ASSERTION WAS REMOVED HERE, and the reason is worth keeping.
-- This script first asserted that the Spoiling batch still held its 18 rows.
-- That passes against production, and CANNOT pass in a clean rebuild: data
-- scripts run in FILENAME order, and `...-mr-bone-spells.sql` sorts BEFORE
-- `...-mr-spoiling-spells.sql`, so when this file runs on a fresh database the
-- Spoiling rows do not exist yet. An assertion about a sibling batch is an
-- assertion about execution order wearing a disguise. Each batch asserts its
-- own rows and nothing else.

SELECT 'no row outside this book was written' AS assertion, count(*) AS got, 0 AS want
  FROM spells WHERE tradition = 'bone' AND source <> 'import';

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('zzzzzzzzzz-mr-bone-spells.sql');
